INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Datenredundanz dasselbe wie Datenkonsistenz?', 2, '[{"text": "Nein", "correct": true, "because": "Redundanz ist Mehrfachspeicherung, Konsistenz ist Widerspruchsfreiheit"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Reduzierung von Datenredundanz?', 3, '[{"text": "Speicherplatz sparen", "correct": true, "because": "Weniger doppelte Daten"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk sichern", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden verringern Datenredundanz?', 5, '[{"text": "Normalisierung", "correct": true, "because": "Entfernt Duplikate"}, {"text": "Primärschlüssel", "correct": true, "because": "Eindeutigkeit sichert"}, {"text": "Grafiktreiber", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenredundanz kann Inkonsistenzen verursachen. b) Sie ist immer nützlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft problematisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse von Datenredundanz?', 4, '[{"text": "Datenbankdesign", "correct": false, "because": "Beeinflusst Redundanz"}, {"text": "Datenintegrität", "correct": false, "because": "Betroffen durch Redundanz"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenredundanz immer negativ ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann für Redundanz nützlich sein"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik hilft gegen Datenredundanz?', 3, '[{"text": "Normalisierung", "correct": true, "because": "Strukturiert Daten"}, {"text": "Texteditor", "correct": false, "because": "Ungeeignet"}, {"text": "Grafiksoftware", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Datenredundanz?', 5, '[{"text": "Inkonsistenz", "correct": true, "because": "Unterschiedliche Versionen"}, {"text": "Mehr Speicherbedarf", "correct": true, "because": "Doppelte Daten"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenredundanz erhöht den Wartungsaufwand. b) Sie ist immer vermeidbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer vermeidbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht zur Reduzierung von Datenredundanz?', 4, '[{"text": "Datenbankdesign", "correct": false, "because": "Struktur optimieren"}, {"text": "Schlüssel", "correct": false, "because": "Eindeutigkeit sichern"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Datenredundanz nur in Datenbanken ein Problem?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Dateisystemen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile kann Datenredundanz haben?', 4, '[{"text": "Schnellerer Zugriff", "correct": true, "because": "Lokale Kopien"}, {"text": "Datensicherung", "correct": true, "because": "Redundanz als Backup"}, {"text": "Weniger Speicher", "correct": false, "because": "Mehr Speicher nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Datenredundanz immer schlecht ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann nützlich sein"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Vermeidung von Datenredundanz?', 3, '[{"text": "Datenbanknormalisierung", "correct": true, "because": "Entfernt Duplikate"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Struktur wichtiger"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenredundanz kann Fehler verursachen. b) Sie ist immer absichtlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft unbeabsichtigt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken fördern Datenredundanz?', 5, '[{"text": "Denormalisierung", "correct": true, "because": "Leistung steigern"}, {"text": "Replikation", "correct": true, "because": "Datensicherung"}, {"text": "Normalisierung", "correct": false, "because": "Reduziert Redundanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Analyse unwichtig?', 3, '[{"text": "Datenbankstruktur", "correct": false, "because": "Bestimmt Redundanz"}, {"text": "Datenaktualität", "correct": false, "because": "Inkonsistenz erkennen"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Datenredundanz bewusst genutzt werden?', 3, '[{"text": "Ja", "correct": true, "because": "z. B. für Performance"}, {"text": "Nein", "correct": false, "because": "Absichtlich einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenredundanz immer vermeidbar ist?', 2, '[{"text": "Nein", "correct": true, "because": "Manchmal gewollt"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Normalisierung bei Datenredundanz?', 4, '[{"text": "Reduziert sie", "correct": true, "because": "Entfernt Duplikate"}, {"text": "Erhöht Speicher", "correct": false, "because": "Verringert Bedarf"}, {"text": "Ändert Hardware", "correct": false, "because": "Irrelevant"}]');
